import{c as o,$ as n,Q as s,j as i,g as t,o as r,n as l,m as c}from"./chunks/framework.Ce_49mA8.js";const w=JSON.parse('{"title":"Project Philosophy","description":"Core values and engineering principles of OmniCraft ERP: continuous accounting without bookkeeping, three core reports, local computer autonomy, and answers to common questions.","frontmatter":{"title":"Project Philosophy","description":"Core values and engineering principles of OmniCraft ERP: continuous accounting without bookkeeping, three core reports, local computer autonomy, and answers to common questions.","order":1,"datePublished":"2026-08-20","dateModified":"2026-11-22"},"headers":[],"relativePath":"docs/introduction.md","filePath":"docs/introduction.md","lastUpdated":1795305600000}'),d={name:"docs/introduction.md"},u={id:"project-philosophy",tabindex:"-1"};function p(h,e,m,y,g,v){const a=n("DocIcon");return s(),i("div",null,[t("h1",u,[r(a,{name:"philosophy"}),e[0]||(e[0]=l(" Project Philosophy ",-1)),e[1]||(e[1]=t("a",{class:"header-anchor",href:"#project-philosophy","aria-label":'Permalink to "Project Philosophy"'},"​",-1))]),e[2]||(e[2]=c('<p><strong>OmniCraft ERP</strong> is engineered for makers and practitioners who create tangible value with their hands and minds: craft manufacturers, service specialists, and independent entrepreneurs with a pragmatic business mindset.</p><p>Traditional accounting software was designed for regulatory authorities: it is weighed down by endless paperwork, complicated charts of accounts, and rigid double-entry bookkeeping. Standard personal expense tracking apps force users into the tedious chore of scanning grocery receipts, yet fail to understand workshop manufacturing costs, work orders, or machinery depreciation.</p><p>OmniCraft ERP is founded on <strong>engineering pragmatism</strong>: management accounting must serve your operations, require minimal effort, and honestly reflect the real return on every invested hour and dollar.</p><hr><h2 id="four-core-principles-of-omnicraft-erp" tabindex="-1">Four Core Principles of OmniCraft ERP <a class="header-anchor" href="#four-core-principles-of-omnicraft-erp" aria-label="Permalink to &quot;Four Core Principles of OmniCraft ERP&quot;">​</a></h2><h3 id="_1-event-driven-accounting-instead-of-bureaucracy" tabindex="-1">1. Event-Driven Accounting Instead of Bureaucracy <a class="header-anchor" href="#_1-event-driven-accounting-instead-of-bureaucracy" aria-label="Permalink to &quot;1. Event-Driven Accounting Instead of Bureaucracy&quot;">​</a></h3><p>The system eliminates double-entry overhead and artificial journal entries. Clear operational analytics emerge naturally from the physical events of your workshop or service studio:</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Craft &amp; Manufacturing:</strong> when receiving raw stock, shipping fees distribute automatically across the unit cost of every decimeter, kilogram, or meter. During assembly, materials are deducted using Moving Average Cost (MAC), and finished goods are dispatched via FIFO, instantly calculating your net product margin.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Services &amp; Maintenance:</strong> work is organized around clean work orders. The system factors in your hourly labor rate, automatically consumes service supplies directly within the job ticket, and records client settlements without formal delivery slips.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Continuous Real-Time Recalculation:</strong> every completed event—receiving materials, closing a work order, finishing a batch, or recording a showcase sale—instantly synchronizes inventory levels, cash balances, and financial performance statements.</div></li></ul><div class="info custom-block"><p class="custom-block-title">Principle of Action Primacy</p><p>You record only the actual physical work of the maker—cash balances, material stock, manufacturing costs, and operating profit recalculate immediately and consistently.</p></div><h3 id="_2-financial-evolution-from-first-orders-to-wealth-management" tabindex="-1">2. Financial Evolution: From First Orders to Wealth Management <a class="header-anchor" href="#_2-financial-evolution-from-first-orders-to-wealth-management" aria-label="Permalink to &quot;2. Financial Evolution: From First Orders to Wealth Management&quot;">​</a></h3><p>Most systems either force a solo maker into complex enterprise bureaucracy or leave growing entrepreneurs stranded when their work outgrows a basic spreadsheet. OmniCraft ERP supports a smooth progression as your enterprise matures:</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Pragmatic, Bureaucracy-Free Start:</strong> early on, independent makers often pay for raw stock with a personal card and spend revenue on everyday living. The system accepts this reality: only operational activities are recorded, and a negative cash flow balance transparently reflects your initial seed capital until the venture turns cash-flow positive.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Isolated Workspaces:</strong> as your activities diversify—such as running a manufacturing studio, a repair shop, and a retail storefront—each runs in an isolated workspace with its own cash register, inventory, and client roster.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Personal Wealth Without Receipt Hoarding (“My Capital” Workspace):</strong> to track household budgets, savings, investments, and real estate, you do not need to log everyday grocery receipts. In PRO mode, personal spending is calculated automatically using the capital balance delta: simply reconcile your bank balances once a month, and the system deduces your exact household expenditures.</div></li></ul><div class="tip custom-block"><p class="custom-block-title">Seamless Scaling</p><p>You begin with a single workspace and intuitive daily workflows—at your workstation, machine, or service counter. As your enterprise expands, the software unlocks multi-project isolation and comprehensive personal wealth tracking without forcing you to re-learn the system or migrate data.</p></div><h3 id="_3-asset-balance-and-real-financial-performance" tabindex="-1">3. Asset Balance and Real Financial Performance <a class="header-anchor" href="#_3-asset-balance-and-real-financial-performance" aria-label="Permalink to &quot;3. Asset Balance and Real Financial Performance&quot;">​</a></h3><p>Purchasing a laser cutter, soldering station, professional service equipment, or specialized hand tools draws liquid cash from your account. However, your wealth has not vanished—cash has simply transformed into durable machinery that continues generating revenue.</p><p>Your asset balance and overall equity are tracked continuously in real time:</p><div class="craft-callout craft-callout-info"><div class="callout-header">Net Assets Formula (Owner Equity / Net Worth)</div><p><strong>Business Equity</strong> = Machinery &amp; Equipment (book value after depreciation) + Raw Stock &amp; Supplies (at MAC) + Finished Inventory (at cost) + Cash &amp; Bank Balances − Business Liabilities &amp; Debts.</p><p style="margin-top:0.65rem;font-size:0.9em;opacity:0.9;"><strong>Consolidated Owner Net Worth</strong> (in the “My Capital” workspace) further unifies operational business equity with personal investments, real estate, and family savings minus private liabilities.</p></div><h4 id="the-triad-of-financial-statements" tabindex="-1">The Triad of Financial Statements <a class="header-anchor" href="#the-triad-of-financial-statements" aria-label="Permalink to &quot;The Triad of Financial Statements&quot;">​</a></h4><p>Three foundational reports complement each other, protecting practitioners and business owners from liquidity crunches and false illusions of profitability:</p><div class="comparison-matrix-wrapper"><table class="craft-comparison-table"><thead><tr><th style="width:24%;">Report</th><th style="width:28%;">Core Question</th><th style="width:48%;">Practical Meaning for Makers and Business Owners</th></tr></thead><tbody><tr><td><strong>Cash Flow</strong><br><small style="color:var(--vp-c-text-3);">Cash Movements</small></td><td><em>Are liquid funds available right now?</em></td><td>Tracks physical cash and bank transfers. Guards against liquidity shortfalls: ensures you have cash on hand for studio rent, consumable replenishment, or vendor invoices.</td></tr><tr><td><strong>P&amp;L (Income Statement)</strong><br><small style="color:var(--vp-c-text-3);">Financial Result</small></td><td><em>Is your operation actually profitable?</em></td><td>Balances total revenue against complete operating expenses (including equipment wear, consumed stock, and overhead). Proves whether individual products, work orders, or services generate real net income.</td></tr><tr><td><strong>Balance Sheet</strong><br><small style="color:var(--vp-c-text-3);">Net Assets</small></td><td><em>What is your entire enterprise worth?</em></td><td>Consolidates all tangible assets (equipment, tools, stock, finished goods, bank balances, and investments) minus liabilities. Demonstrates whether your venture&#39;s equity and personal net worth are compounding year over year.</td></tr></tbody></table></div><div class="tip custom-block"><p class="custom-block-title">Continuous Financial Memory</p><p>The system continuously preserves the historical retrospective of key indicators. This gives you an honest, uninterrupted view of your business trajectory without risking lost data: from monthly seasonal revenue cycles to the long-term compounding growth of your enterprise equity.</p></div><h3 id="_4-absolute-data-sovereignty-and-local-ai-omni" tabindex="-1">4. Absolute Data Sovereignty and Local AI Omni <a class="header-anchor" href="#_4-absolute-data-sovereignty-and-local-ai-omni" aria-label="Permalink to &quot;4. Absolute Data Sovereignty and Local AI Omni&quot;">​</a></h3><p>OmniCraft ERP is engineered to protect your operational sovereignty. The platform runs entirely offline on your local computer, free from reliance on external cloud servers or risks of unexpected service shutdowns.</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Complete Local Autonomy:</strong> your database is stored strictly on your local storage drive in SQLite format. Production recipes, client contacts, cost estimates, and account balances are never transmitted to third-party developer servers.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Built-in AI Assistant Omni:</strong> the internal intelligent partner acts as an experienced workshop mentor and autonomous agent. It assists in unit cost calculations, inventory analysis, order scheduling, and practical operational tasks through the unified tool registry and open Model Context Protocol.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Direct Personal AI Key Without Intermediaries:</strong> requests travel straight from your computer to your preferred AI provider (`OpenAI`, `Google Gemini`, `DeepSeek`, `OpenRouter`) via your personal access key (API key) without intermediate developer proxy servers. For users requiring autonomous operation without internet access, running local models directly on your hardware via `Ollama` is natively supported.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Integration with External Assistants (MCP Protocol):</strong> allows external coding and reasoning environments (`Cursor`, `Claude Desktop`, `Antigravity`) to safely interact with your studio data under your complete oversight.</div></li></ul><div class="tip custom-block"><p class="custom-block-title">Choice Between Cloud and Local AI</p><p>You retain full control over your intelligence setup. You can connect leading cloud models via your personal access key (API) or run a local model via <code>Ollama</code>—in this offline mode, all inferences and calculations process directly on your workstation hardware without internet connectivity.</p></div><hr><h2 id="answers-to-common-questions" tabindex="-1">Answers to Common Questions <a class="header-anchor" href="#answers-to-common-questions" aria-label="Permalink to &quot;Answers to Common Questions&quot;">​</a></h2><div class="faq-grid"><details class="faq-item"><summary class="faq-summary">Why does the program run locally on a PC rather than as a cloud service?</summary><div class="faq-content"><p>Local operation guarantees the absolute independence and security of your commercial data. Your database resides strictly on your machine: your entire studio and accounting history are packaged into a compact file that can be easily backed up to an external drive or moved to a new PC without complex setups. The application never stops opening due to network issues, platform bans, or temporary internet outages at your workplace. You own your data forever.</p></div></details><details class="faq-item"><summary class="faq-summary">Can the AI assistant Omni operate completely offline?</summary><div class="faq-content"><p>Yes. For offline operation without an active internet connection, simply connect a free local <code>Ollama</code> instance. In this scenario, assistant Omni and accounting tools operate entirely on your own computer hardware.</p></div></details><details class="faq-item"><summary class="faq-summary">Does OmniCraft ERP replace statutory tax and corporate accounting software?</summary><div class="faq-content"><p>OmniCraft ERP is strictly dedicated to <strong>internal management accounting</strong>—empowering you to know your true product margins, actual operating profit, and net worth for strategic business decisions. Mandatory tax declarations and government filings are handled separately through your accountant or official tax portal.</p></div></details><details class="faq-item"><summary class="faq-summary">Why is a negative Cash Flow balance considered normal during early stages?</summary><div class="faq-content"><p>In practice, independent makers frequently buy equipment or initial raw materials with personal funds without recording a formal equity contribution. The system does not lock up: a negative cash flow transparently records your cumulative personal investment in the project, which the business repays as sales compound.</p></div></details><details class="faq-item"><summary class="faq-summary">How does the system separate personal and business funds without receipt hoarding?</summary><div class="faq-content"><p>In the “My Capital” workspace, personal expenditure is calculated via the capital balance delta. Instead of scanning daily grocery receipts, you simply reconcile bank account balances once a month. The system compares changes in total net worth against business income, precisely determining household living costs.</p></div></details></div><hr><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><div class="cta-grid"><div class="cta-card featured-cta"><div><div class="cta-card-badge brand-badge">Hands-on Guide</div><h3>Quick Start &amp; Installation</h3><p> Step-by-step tutorial from downloading the application to your first batch and unit cost calculation in 15 minutes. </p></div><a href="/docs/getting-started" class="vp-button brand cta-icon-btn"><span>Get Started</span><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="cta-btn-icon"><line x1="5" y1="12" x2="19" y2="12"></line><polyline points="12 5 19 12 12 19"></polyline></svg></a></div><div class="cta-card"><div><div class="cta-card-badge">System Architecture</div><h3>Workspaces Overview</h3><p> Organizing independent activities: craft manufacturing, client service orders, and consolidated personal wealth. </p></div><a href="/docs/spaces/general" class="vp-button alt cta-icon-btn"><span>Explore Workspaces</span><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="cta-btn-icon"><line x1="5" y1="12" x2="19" y2="12"></line><polyline points="12 5 19 12 12 19"></polyline></svg></a></div></div>',31))])}const b=o(d,[["render",p]]);export{w as __pageData,b as default};
